# Job to be done: compare complete first-shipment options under the same review basis and identify which launch actions the supplier can authorize.
# Finish with a scoped preparation/booking approval or an explicit hold, with exact versions, reasons, conditions and owners for handoff.
# Calculated support is separate from retained evidence and human authorization; this description does not dispatch a shipment.
# Fictional premises for exploring phrase composition; no retained evidence or authorization.
Decision case "LAUNCH-01" named "Example · Review a first-shipment decision".

# Review context
# Responsibility (launch): share typed identities, review context and the rules that connect complete selections to module calculations.
Launch "LAUNCH-01" uses basis "BASIS-01/v1" and snapshot "SNAP-02" for shipment "FIRST-SHIPMENT".

# Complete selections
Explore movements "MOVE-C/standard, MOVE-B/rush", pickup days "6, 10" and spending authorities "CAP-01, CAP-02" for launch "LAUNCH-01".

# Shared ontology: questions, services and named readiness requirements.
# Responsibility: declare the business relationships without inventing evidence, answers or permission.
# Quote footprints below preserve the original 600-case execution scope independently of the current proposal.
entities as yaml:
  DQ-LAUNCH:
    type: "DecisionQuestion"
    fields:
      text: "Which first-shipment actions can the supplier authorize?"
      level: "shared"
      responsibleRole: "supplier-release-owner"
  DQ-BASIS:
    type: "DecisionQuestion"
    fields:
      text: "What shipment basis is established?"
      level: "local"
      responsibleRole: "item-reviewer"
      contributesTo:
        - {"ref":"DQ-LAUNCH"}
  DQ-ORDER:
    type: "DecisionQuestion"
    fields:
      text: "What order commitment applies?"
      level: "local"
      responsibleRole: "order-reviewer"
      contributesTo:
        - {"ref":"DQ-LAUNCH"}
  DQ-ROUTE:
    type: "DecisionQuestion"
    fields:
      text: "What movement can be supported?"
      level: "local"
      responsibleRole: "logistics-reviewer"
      contributesTo:
        - {"ref":"DQ-LAUNCH"}
  DQ-EXCHANGE:
    type: "DecisionQuestion"
    fields:
      text: "Does the accepted system test apply?"
      level: "local"
      responsibleRole: "systems-reviewer"
      contributesTo:
        - {"ref":"DQ-LAUNCH"}
  DQ-COST:
    type: "DecisionQuestion"
    fields:
      text: "What expense is supported and permitted?"
      level: "local"
      responsibleRole: "finance-reviewer"
      contributesTo:
        - {"ref":"DQ-LAUNCH"}
  DQ-PLAN:
    type: "DecisionQuestion"
    fields:
      text: "Are the contributing answers compatible?"
      level: "local"
      responsibleRole: "review-coordinator"
      contributesTo:
        - {"ref":"DQ-LAUNCH"}
  DQ-REVIEW:
    type: "DecisionQuestion"
    fields:
      text: "Which launch actions may proceed?"
      level: "local"
      responsibleRole: "supplier-release-owner"
      contributesTo:
        - {"ref":"DQ-LAUNCH"}
  PROBLEM-FIRST-SHIPMENT:
    type: "DecisionProblem"
    fields:
      sharedQuestion:
        ref: "DQ-LAUNCH"
      contributingQuestions:
        - {"ref":"DQ-BASIS"}
        - {"ref":"DQ-ORDER"}
        - {"ref":"DQ-ROUTE"}
        - {"ref":"DQ-EXCHANGE"}
        - {"ref":"DQ-COST"}
        - {"ref":"DQ-PLAN"}
        - {"ref":"DQ-REVIEW"}
      subject:
        ref: "SHIPMENT-01"
      actionScope: "First-shipment preparation and booking"
  SERVICE-COL:
    type: "ServiceOption"
    fields:
      name: "Standard collect service"
  SERVICE-RUSH:
    type: "ServiceOption"
    fields:
      name: "Rush prepaid service"
  SHIPMENT-01:
    type: "Movement"
    fields:
