        - {"ref":"SERVICE-COL"}
        - {"ref":"SERVICE-RUSH"}
      requiredChecks:
        - {"ref":"CHECK-BASIS-R01"}
        - {"ref":"CHECK-BASIS-R02"}
        - {"ref":"CHECK-ORDER-R03"}
        - {"ref":"CHECK-ROUTE-R04"}
        - {"ref":"CHECK-ROUTE-R05"}
        - {"ref":"CHECK-ROUTE-R06"}
        - {"ref":"CHECK-ROUTE-R08"}
        - {"ref":"CHECK-ROUTE-R09"}
        - {"ref":"CHECK-ROUTE-R10"}
